//! Build-time brand metadata, generated by `scripts/brand/apply.js` from
//! `brands/<id>/brand.json`. Do not edit by hand; on this branch it carries
//! the Folly Launcher statistics prefix and product name.

/// Prefix prepended to the reported version on the upstream statistics
/// server, as required by LICENSE.EXTRA for modified distributions
/// (e.g. "jlucraft" produces "folly-1.3.1"). Empty for the unmodified
/// upstream build.
pub const STATS_VERSION_PREFIX: &str = "folly";

/// Display name reported to local auth servers (e.g. the loopback
/// Yggdrasil metadata serverName).
pub const PRODUCT_NAME: &str = "Folly Launcher";

pub const DEEPLINK_PREFIX: &str = "folly://";
pub const RELEASES_API_URL: &str =
  "https://api.github.com/repos/JLUCraft/FollyLauncher/releases/latest";
pub const RELEASES_DOWNLOAD_URL: &str =
  "https://github.com/JLUCraft/FollyLauncher/releases/download";
